<script setup>
import { reactive } from 'vue'; import { Head, Link, router } from '@inertiajs/vue3'; import { KeyRound, Pencil, Plus, Users } from 'lucide-vue-next'; import MainLayout from '@/layouts/MainLayout.vue'
const props=defineProps({accounts:{type:Object,required:true},units:{type:Array,required:true},filters:{type:Object,required:true}}); const filters=reactive({...props.filters}); const apply=()=>router.get('/admin/accounts',filters,{preserveState:true,replace:true}); const toggle=(account)=>{if(confirm(`${account.is_active?'Nonaktifkan':'Aktifkan'} akun ${account.name}?`)) router.patch(`/admin/accounts/${account.id}/status`,{is_active:!account.is_active},{preserveScroll:true})}
</script>
<template><Head title="Akun Wilayah"/><MainLayout><div class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-sm font-medium text-orange-600">Administrasi akses</p><h2 class="mt-1 text-2xl font-semibold text-slate-950">Akun Wilayah</h2><p class="mt-2 text-sm text-slate-600">Kelola akun operator Daop dan Divre tanpa akses Pusat.</p></div><Link href="/admin/accounts/create" class="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-[#ea580c] px-4 text-sm font-semibold text-white"><Plus :size="18"/>Tambah akun</Link></div>
<form class="mb-5 grid gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm lg:grid-cols-[1fr_14rem_12rem_auto]" @submit.prevent="apply"><input v-model="filters.search" type="search" placeholder="Cari nama atau username…" class="h-11 rounded-lg border border-slate-300 px-3 text-sm"><select v-model="filters.unit_kerja_id" class="h-11 rounded-lg border border-slate-300 px-3 text-sm"><option value="">Semua unit</option><option v-for="unit in units" :key="unit.id" :value="String(unit.id)">{{ unit.code }}</option></select><select v-model="filters.status" class="h-11 rounded-lg border border-slate-300 px-3 text-sm"><option value="">Semua status</option><option value="1">Aktif</option><option value="0">Nonaktif</option></select><button class="h-11 rounded-lg bg-[#171650] px-5 text-sm font-medium text-white">Terapkan</button></form>
<section class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div v-if="accounts.data.length" class="overflow-x-auto"><table class="min-w-full divide-y divide-slate-200"><thead class="bg-slate-50"><tr><th class="px-5 py-3 text-left text-xs uppercase text-slate-500">Pengguna</th><th class="px-5 py-3 text-left text-xs uppercase text-slate-500">Unit</th><th class="px-5 py-3 text-left text-xs uppercase text-slate-500">Status</th><th class="px-5 py-3 text-right text-xs uppercase text-slate-500">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="account in accounts.data" :key="account.id"><td class="px-5 py-4"><p class="text-sm font-semibold text-slate-900">{{account.name}}</p><p class="mt-1 text-xs text-slate-500">@{{account.username}}</p></td><td class="px-5 py-4 text-sm">{{account.unit_kerja?.code}}</td><td class="px-5 py-4"><button class="rounded-full px-2.5 py-1 text-xs font-medium" :class="account.is_active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600'" @click="toggle(account)">{{account.is_active?'Aktif':'Nonaktif'}}</button></td><td class="px-5 py-4 text-right"><div class="flex justify-end gap-1"><Link :href="`/admin/accounts/${account.id}/edit`" class="rounded-lg p-2 text-[#2d2a70] hover:bg-blue-50" aria-label="Edit akun"><Pencil :size="17"/></Link><Link :href="`/admin/accounts/${account.id}/password`" class="rounded-lg p-2 text-slate-600 hover:bg-slate-100" aria-label="Atur ulang kata sandi"><KeyRound :size="17"/></Link></div></td></tr></tbody></table></div><div v-else class="py-16 text-center"><Users :size="28" class="mx-auto text-slate-400"/><h3 class="mt-3 font-semibold">Akun tidak ditemukan</h3><p class="mt-2 text-sm text-slate-500">Sesuaikan filter atau tambahkan akun wilayah baru.</p></div><div v-if="accounts.links.length>3" class="flex gap-1 border-t p-4"><Link v-for="link in accounts.links" :key="link.label" :href="link.url||'#'" class="rounded border px-3 py-2 text-xs" :class="link.active?'bg-[#171650] text-white':'text-slate-600'">{{link.label.replace('&laquo; Previous','Sebelumnya').replace('Next &raquo;','Berikutnya')}}</Link></div></section></MainLayout></template>
